import{_ as t,o as a,c as o,a3 as d}from"./chunks/framework.CRbjHCyB.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"clice/guide/configuration.md","filePath":"en/clice/guide/configuration.md"}'),i={name:"clice/guide/configuration.md"};function r(n,e,s,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>clice reads configuration from <code>clice.toml</code> in the workspace root, or from <code>.clice/config.toml</code> if the former does not exist. Configuration can also be passed via LSP <code>initializationOptions</code> (JSON format); values from <code>initializationOptions</code> override the config file, and defaults fill in whatever remains unset after the merge.</p><p>Configuration is read once at server startup. Changing it — either file — requires restarting the server; there is no hot reload.</p><p>A JSON schema of the whole configuration is published at <a href="/clice-config.schema.json"><code>clice-config.schema.json</code></a>; editors that validate TOML or JSON against a schema can point at it.</p><h2 id="variable-substitution" tabindex="-1">Variable Substitution <a class="header-anchor" href="#variable-substitution" aria-label="Permalink to &quot;Variable Substitution&quot;">​</a></h2><p>The following variable is supported in string values:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th></tr></thead><tbody><tr><td><code>${workspace}</code></td><td>The workspace directory provided by the client</td></tr></tbody></table><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><h3 id="project-cache-dir" tabindex="-1"><code>project.cache_dir</code> <a class="header-anchor" href="#project-cache-dir" aria-label="Permalink to &quot;`project.cache_dir`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr></tbody></table><p>Directory for the unified on-disk cache (PCH, PCM and index artifacts). Empty derives it from XDG_CACHE_HOME (or <code>~/.cache</code>) with a per-workspace subdirectory named after the workspace plus a short hash, falling back to <code>${workspace}/.clice</code>; the resolved path is printed at startup.</p><h3 id="project-logging-dir" tabindex="-1"><code>project.logging_dir</code> <a class="header-anchor" href="#project-logging-dir" aria-label="Permalink to &quot;`project.logging_dir`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>&quot;&quot;</code></td></tr></tbody></table><p>Directory for log files; empty derives <code>${cache_dir}/logs</code>. Each server session logs into its own timestamped subdirectory.</p><h3 id="project-compile-commands-paths" tabindex="-1"><code>project.compile_commands_paths</code> <a class="header-anchor" href="#project-compile-commands-paths" aria-label="Permalink to &quot;`project.compile_commands_paths`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Paths searched for compile_commands.json — file paths, or directories to look inside. When these all miss — or the list is empty — the workspace root and then each of its immediate subdirectories are searched.</p><h3 id="project-enable-indexing" tabindex="-1"><code>project.enable_indexing</code> <a class="header-anchor" href="#project-enable-indexing" aria-label="Permalink to &quot;`project.enable_indexing`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Build the background index that serves cross-TU features (find references, workspace symbols, ...).</p><h3 id="project-index-db" tabindex="-1"><code>project.index_db</code> <a class="header-anchor" href="#project-index-db" aria-label="Permalink to &quot;`project.index_db`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>&quot;lmdb&quot;</code></td></tr></tbody></table><p>Index persistence backend: &quot;lmdb&quot; (single database file) or &quot;files&quot; (one file per blob).</p><h3 id="project-readonly" tabindex="-1"><code>project.readonly</code> <a class="header-anchor" href="#project-readonly" aria-label="Permalink to &quot;`project.readonly`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>string</code></td><td><code>&quot;off&quot;</code></td></tr></tbody></table><p>Read-only serving for open files: &quot;off&quot; targets a full AST for every open file — builds are pulled by the first request that needs them, with the index answering in the meantime; &quot;on&quot; never builds a PCH — reads serve from the index alone (a cold file jumps the indexing queue), while completion and signature help still compile on demand without a preamble; &quot;auto&quot; starts every file as &quot;on&quot;, switches it to &quot;off&quot; at the first edit intent (edit, completion, signature help, context switch), and falls back to &quot;off&quot; for a file the index cannot serve. Feature routing always answers from the best source currently available.</p><h3 id="project-idle-timeout-ms" tabindex="-1"><code>project.idle_timeout_ms</code> <a class="header-anchor" href="#project-idle-timeout-ms" aria-label="Permalink to &quot;`project.idle_timeout_ms`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>3000</code></td></tr></tbody></table><p>Idle delay in milliseconds before background indexing starts.</p><h3 id="project-test-hooks" tabindex="-1"><code>project.test_hooks</code> <a class="header-anchor" href="#project-test-hooks" aria-label="Permalink to &quot;`project.test_hooks`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Enable the clice/internal test hooks used by the test harness.</p><h3 id="project-stateful-worker-count" tabindex="-1"><code>project.stateful_worker_count</code> <a class="header-anchor" href="#project-stateful-worker-count" aria-label="Permalink to &quot;`project.stateful_worker_count`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>2</code></td></tr></tbody></table><p>Number of stateful workers — they hold ASTs in memory and serve queries (hover, semantic tokens, ...); <code>0</code> is invalid and falls back to the default.</p><h3 id="project-stateless-worker-count" tabindex="-1"><code>project.stateless_worker_count</code> <a class="header-anchor" href="#project-stateless-worker-count" aria-label="Permalink to &quot;`project.stateless_worker_count`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td>—</td></tr></tbody></table><p>Initial number of stateless workers — they handle ephemeral tasks (PCH/PCM builds, completion, signature help); defaults to half the machine&#39;s parallelism, at least 2. <code>0</code> is invalid and falls back to that default.</p><h3 id="project-min-stateless-worker-count" tabindex="-1"><code>project.min_stateless_worker_count</code> <a class="header-anchor" href="#project-min-stateless-worker-count" aria-label="Permalink to &quot;`project.min_stateless_worker_count`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>1</code></td></tr></tbody></table><p>Lower bound for dynamic stateless-worker scaling; <code>0</code> is invalid and falls back to the default.</p><h3 id="project-max-stateless-worker-count" tabindex="-1"><code>project.max_stateless_worker_count</code> <a class="header-anchor" href="#project-max-stateless-worker-count" aria-label="Permalink to &quot;`project.max_stateless_worker_count`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td>—</td></tr></tbody></table><p>Upper bound for dynamic stateless-worker scaling; <code>0</code> means the machine&#39;s parallelism, which is also the default.</p><h3 id="project-worker-memory-limit" tabindex="-1"><code>project.worker_memory_limit</code> <a class="header-anchor" href="#project-worker-memory-limit" aria-label="Permalink to &quot;`project.worker_memory_limit`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint64</code></td><td><code>4294967296</code></td></tr></tbody></table><p>Per-stateful-worker memory limit in bytes; <code>0</code> is invalid and falls back to the default. Not yet enforced: parsed, but memory-based eviction is not implemented.</p><h2 id="tracker" tabindex="-1">Tracker <a class="header-anchor" href="#tracker" aria-label="Permalink to &quot;Tracker&quot;">​</a></h2><p>The file tracker polls for changes that happen outside the editor (a <code>git checkout</code>, a regenerated <code>compile_commands.json</code>, code generators writing headers) so the server picks them up without a restart. Setting an interval to <code>0</code> disables that polling loop.</p><h3 id="tracker-cdb-poll-seconds" tabindex="-1"><code>tracker.cdb_poll_seconds</code> <a class="header-anchor" href="#tracker-cdb-poll-seconds" aria-label="Permalink to &quot;`tracker.cdb_poll_seconds`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>3</code></td></tr></tbody></table><p>Compilation database poll interval in seconds; 0 disables polling.</p><h3 id="tracker-workspace-poll-seconds" tabindex="-1"><code>tracker.workspace_poll_seconds</code> <a class="header-anchor" href="#tracker-workspace-poll-seconds" aria-label="Permalink to &quot;`tracker.workspace_poll_seconds`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>30</code></td></tr></tbody></table><p>Workspace file sweep interval in seconds; 0 disables polling.</p><h2 id="hover" tabindex="-1">Hover <a class="header-anchor" href="#hover" aria-label="Permalink to &quot;Hover&quot;">​</a></h2><p>The <code>[hover]</code> section controls how hover cards render.</p><h3 id="hover-parse-comment-as-markdown" tabindex="-1"><code>hover.parse_comment_as_markdown</code> <a class="header-anchor" href="#hover-parse-comment-as-markdown" aria-label="Permalink to &quot;`hover.parse_comment_as_markdown`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Render the hover card as markdown; <code>false</code> produces plain text for clients that cannot display it.</p><h3 id="hover-show-aka" tabindex="-1"><code>hover.show_aka</code> <a class="header-anchor" href="#hover-show-aka" aria-label="Permalink to &quot;`hover.show_aka`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Show the desugared form of a type, e.g. <code>vector&lt;int&gt;::size_type (aka unsigned long)</code>.</p><h2 id="inlay-hints" tabindex="-1">Inlay Hints <a class="header-anchor" href="#inlay-hints" aria-label="Permalink to &quot;Inlay Hints&quot;">​</a></h2><p>The <code>[inlay_hints]</code> section controls which inlay hint categories the server produces. A client-side refresh then requests hints with the updated values; no recompile is involved.</p><h3 id="inlay-hints-enabled" tabindex="-1"><code>inlay_hints.enabled</code> <a class="header-anchor" href="#inlay-hints-enabled" aria-label="Permalink to &quot;`inlay_hints.enabled`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Master switch: <code>false</code> disables all inlay hints.</p><h3 id="inlay-hints-parameters" tabindex="-1"><code>inlay_hints.parameters</code> <a class="header-anchor" href="#inlay-hints-parameters" aria-label="Permalink to &quot;`inlay_hints.parameters`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Parameter name hints at call sites, e.g. <code>draw(width: 800, height: 600)</code>, including <code>&amp;</code> markers for arguments passed by mutable reference.</p><h3 id="inlay-hints-deduced-types" tabindex="-1"><code>inlay_hints.deduced_types</code> <a class="header-anchor" href="#inlay-hints-deduced-types" aria-label="Permalink to &quot;`inlay_hints.deduced_types`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Deduced type hints for <code>auto</code> variables, structured bindings and deduced return types.</p><h3 id="inlay-hints-designators" tabindex="-1"><code>inlay_hints.designators</code> <a class="header-anchor" href="#inlay-hints-designators" aria-label="Permalink to &quot;`inlay_hints.designators`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Field designator hints in aggregate initialization, e.g. <code>.x=</code> and <code>.y=</code> in <code>Point{1, 2}</code>.</p><h3 id="inlay-hints-block-end" tabindex="-1"><code>inlay_hints.block_end</code> <a class="header-anchor" href="#inlay-hints-block-end" aria-label="Permalink to &quot;`inlay_hints.block_end`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p><code>// name</code> hints after the closing brace of long blocks (functions, types, namespaces, control flow).</p><h3 id="inlay-hints-default-arguments" tabindex="-1"><code>inlay_hints.default_arguments</code> <a class="header-anchor" href="#inlay-hints-default-arguments" aria-label="Permalink to &quot;`inlay_hints.default_arguments`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Show the default arguments a call omitted, abbreviated when long.</p><h3 id="inlay-hints-type-name-limit" tabindex="-1"><code>inlay_hints.type_name_limit</code> <a class="header-anchor" href="#inlay-hints-type-name-limit" aria-label="Permalink to &quot;`inlay_hints.type_name_limit`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>32</code></td></tr></tbody></table><p>Byte budget for rendered hint text: over-long deduced types fall back to a sugared spelling or are dropped, over-long default arguments are abbreviated. <code>0</code> means no limit.</p><h2 id="code-completion" tabindex="-1">Code Completion <a class="header-anchor" href="#code-completion" aria-label="Permalink to &quot;Code Completion&quot;">​</a></h2><p>The <code>[code_completion]</code> section controls completion item assembly.</p><h3 id="code-completion-enable-keyword-snippet" tabindex="-1"><code>code_completion.enable_keyword_snippet</code> <a class="header-anchor" href="#code-completion-enable-keyword-snippet" aria-label="Permalink to &quot;`code_completion.enable_keyword_snippet`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Complete keywords as snippets (not yet implemented).</p><h3 id="code-completion-enable-function-arguments-snippet" tabindex="-1"><code>code_completion.enable_function_arguments_snippet</code> <a class="header-anchor" href="#code-completion-enable-function-arguments-snippet" aria-label="Permalink to &quot;`code_completion.enable_function_arguments_snippet`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Insert function arguments as a snippet when completing a call. For functions this applies to individually listed overloads, so it requires <code>bundle_overloads = false</code>; function-like macros have no overload sets and always take the snippet.</p><h3 id="code-completion-enable-template-arguments-snippet" tabindex="-1"><code>code_completion.enable_template_arguments_snippet</code> <a class="header-anchor" href="#code-completion-enable-template-arguments-snippet" aria-label="Permalink to &quot;`code_completion.enable_template_arguments_snippet`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Insert template arguments as a snippet on completion (not yet implemented).</p><h3 id="code-completion-insert-paren-in-function-call" tabindex="-1"><code>code_completion.insert_paren_in_function_call</code> <a class="header-anchor" href="#code-completion-insert-paren-in-function-call" aria-label="Permalink to &quot;`code_completion.insert_paren_in_function_call`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>false</code></td></tr></tbody></table><p>Insert parentheses when completing a function call (not yet implemented).</p><h3 id="code-completion-bundle-overloads" tabindex="-1"><code>code_completion.bundle_overloads</code> <a class="header-anchor" href="#code-completion-bundle-overloads" aria-label="Permalink to &quot;`code_completion.bundle_overloads`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>bool</code></td><td><code>true</code></td></tr></tbody></table><p>Collapse an overload set into a single completion item.</p><h3 id="code-completion-limit" tabindex="-1"><code>code_completion.limit</code> <a class="header-anchor" href="#code-completion-limit" aria-label="Permalink to &quot;`code_completion.limit`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>uint32</code></td><td><code>0</code></td></tr></tbody></table><p>Maximum number of completion items (not yet implemented).</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><p><code>[[rules]]</code> is an array of rule objects. Rules are matched in declaration order — later rules override earlier ones.</p><h3 id="rules-patterns" tabindex="-1"><code>[rules].patterns</code> <a class="header-anchor" href="#rules-patterns" aria-label="Permalink to &quot;`[rules].patterns`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Glob patterns selecting the files this rule applies to: <code>*</code> matches within a path segment (a pattern of just <code>*</code> matches any path), <code>?</code> a single character, <code>**</code> any number of segments, <code>{a,b}</code> alternatives, <code>[0-9]</code> a character range, <code>[!...]</code> a negated range.</p><h3 id="rules-append" tabindex="-1"><code>[rules].append</code> <a class="header-anchor" href="#rules-append" aria-label="Permalink to &quot;`[rules].append`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Compilation flags appended for matching files, e.g. <code>[&quot;-std=c++20&quot;, &quot;-DNDEBUG&quot;]</code>.</p><h3 id="rules-remove" tabindex="-1"><code>[rules].remove</code> <a class="header-anchor" href="#rules-remove" aria-label="Permalink to &quot;`[rules].remove`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>array of string</code></td><td><code>[]</code></td></tr></tbody></table><p>Compilation flags removed for matching files, e.g. <code>[&quot;-Wall&quot;]</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">compile_commands_paths = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;${workspace}/build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;${workspace}/cmake-build-debug&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">clang_tidy = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">append = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-std=c++23&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;**/test/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">append = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-DTEST_MODE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div>',119)])])}const b=t(i,[["render",r]]);export{u as __pageData,b as default};
